{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://amap-spec/schemas/peer-statement.schema.json",
  "title": "peer-statement",
  "description": "runtime -> runtime: the signed statement that carr\
    ies a peer message between hosts. AMMP, section \"Peer Traffic B\
    etween Hosts\". The sending runtime signs the statement's exact \
    UTF-8 bytes with Ed25519 and ships both in one AMAP-Peer-Stateme\
    nt header field (section \"Carriage, and the Candidate the Verif\
    ier Sees\"); the receiving runtime verifies the signature over t\
    he received bytes before parsing, then validates against this sc\
    hema. CLOSED at every level, unlike the runtime-authored notices\
    : these are signed bytes another runtime acts on, a member the r\
    eceiver does not know is a member it cannot bind to what it publ\
    ishes, and the version member `v` is the only evolution path. A \
    statement that fails this schema fails verification, and the mes\
    sage is demoted to mail (sections \"Verification\" and \"Outcome\
    s\"). Numbers are lexical integers (no fraction or exponent) an\
    d strings contain no unpaired surrogate (section \"The Statement\
    \", checked at check 5(b) of section \"Verification\"); the sche\
    ma cannot express either, nor calendar validity, interval order\
    , the entropy of `id`, or any binding to the message: those are \
    the verification steps of section \"Verification\".",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "v",
    "key_id",
    "kind",
    "id",
    "from",
    "to",
    "ts",
    "subject",
    "body_sha256",
    "attachments"
  ],
  "properties": {
    "v": {
      "type": "integer",
      "const": 1
    },
    "key_id": {
      "type": "string",
      "description": "names one key in the signing peer's configure\
    d key set; opaque, unique within that set, 1-64 characters.",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,63}(?!\\n)$"
    },
    "kind": {
      "const": "peer"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "description": "the peer message id (section \"Correlation an\
    d Replies\"), bare. A sending runtime mints it under ^[A-Za-z0-9\
    _][A-Za-z0-9_-]*$ (hex, or base64url re-minted if it would star\
    t with '-'): the notice_id charset without '.', so its Message-I\
    D encoding <id@domain> is a valid msg-id (section \"The Statemen\
    t\"); the receiver publishes it as message.id.",
      "pattern": "^[A-Za-z0-9_][A-Za-z0-9_-]*(?!\\n)$"
    },
    "in_reply_to": {
      "type": "string",
      "minLength": 1,
      "description": "the peer message id this message answers (sect\
    ion \"Correlation and Replies\"), bare, minted by the other runt\
    ime under the same pattern. Absent on a fresh task. Resolved aga\
    inst the receiver's ledger with the participants bound (section \
    \"Correlation and Edges Between Hosts\").",
      "pattern": "^[A-Za-z0-9_][A-Za-z0-9_-]*(?!\\n)$"
    },
    "from": {
      "type": "string",
      "minLength": 1,
      "description": "bare addr-spec of the sending agent; its domai\
    n MUST be one of the signing peer's configured domains.",
      "pattern": "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9.-]+(?\
    !\\n)$"
    },
    "to": {
      "type": "string",
      "minLength": 1,
      "description": "bare addr-spec of the one receiving agent (sec\
    tion \"Addressing\": a peer message is addressed to one agent).",
      "pattern": "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9.-]+(?\
    !\\n)$"
    },
    "ts": {
      "type": "string",
      "description": "when the sending runtime signed: RFC 3339 UTC\
    , whole seconds, upper-case T and Z, no offset. MUST be a real c\
    alendar instant (section \"The Statement\").",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9\
    ]{2}Z(?!\\n)$"
    },
    "subject": {
      "type": "string",
      "description": "the subject the receiver publishes as message.\
    subject; no control characters.",
      "pattern": "^[^\u0000-\u001f]*(?!\\n)$"
    },
    "body_sha256": {
      "type": "string",
      "description": "SHA-256 of the UTF-8 encoding of the body_tex\
    t the receiver will publish, lower-case hex.",
      "pattern": "^[a-f0-9]{64}(?!\\n)$"
    },
    "attachments": {
      "type": "array",
      "description": "one entry per attachment, in order; empty whe\
    n there are none.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "sha256",
          "size_bytes",
          "filename",
          "media_type"
        ],
        "properties": {
          "sha256": {
            "type": "string",
            "pattern": "^[a-f0-9]{64}(?!\\n)$"
          },
          "size_bytes": {
            "type": "integer",
            "minimum": 0
          },
          "filename": {
            "type": "string",
            "minLength": 1
          },
          "media_type": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "sender_exposure": {
      "type": "object",
      "additionalProperties": false,
      "description": "section \"Sender Exposure\", asserted by the s\
    ending runtime; omitted when it made no assessment. Timestamps i\
    n ts's format; window_start <= window_end; last_external_deliver\
    y_ts present iff external_mail_delivered is true, and then withi\
    n the window; asserted_by is the signing runtime's configured ru\
    ntime address (section \"The Statement\"; checks 5(b) and 8 of s\
    ection \"Verification\").",
      "required": [
        "asserted_by",
        "external_mail_delivered",
        "window_start",
        "window_end"
      ],
      "properties": {
        "asserted_by": {
          "type": "string",
          "minLength": 1,
          "pattern": "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9.-\
    ]+(?!\\n)$"
        },
        "external_mail_delivered": {
          "type": "boolean"
        },
        "window_start": {
          "type": "string",
          "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:\
    [0-9]{2}Z(?!\\n)$"
        },
        "window_end": {
          "type": "string",
          "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:\
    [0-9]{2}Z(?!\\n)$"
        },
        "last_external_delivery_ts": {
          "type": "string",
          "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:\
    [0-9]{2}Z(?!\\n)$"
        },
        "derived_from": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "pattern": "^[A-Za-z0-9_][A-Za-z0-9_.-]*(?!\\n)$"
          }
        }
      },
      "if": {
        "required": [
          "external_mail_delivered"
        ],
        "properties": {
          "external_mail_delivered": {
            "const": true
          }
        }
      },
      "then": {
        "required": [
          "last_external_delivery_ts"
        ]
      }
    },
    "sender_since": {
      "type": "string",
      "description": "OPTIONAL (section \"Optional: Sender Age, and \
    Deployment Admission Policy\"): when the sending runtime first e\
    nrolled the sending agent's identity (as that runtime defines id\
    entity), from its durable registry; same format as ts and not la\
    ter than ts. A runtime assertion, not a sender claim. Never rese\
    t for a continuation of the same identity (restart, rebind, re-c\
    reation, key rotation); a new enrolment starts a new value. A re\
    ceiver enforcing a sender age keeps the last value per (runtime\
    , from) and refuses an earlier one as inconsistent. Absence mean\
    s NOT ASSERTED, never 'new'.",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9\
    ]{2}Z(?!\\n)$"
    }
  }
}

NOTE: '\' line wrapping per RFC 8792

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://amap-spec/schemas/peer-control.schema.json",
  "title": "peer-control",
  "description": "runtime -> runtime: the signed control notice a re\
    ceiving runtime sends to a configured sending runtime about wha\
    t it did with an authenticated peer statement that it did not pl\
    ace (refused, dropped, or demoted). AMMP, section \"Control Noti\
    ces\". Carried in an AMAP-Peer-Control header field with the sam\
    e k/s/b grammar as AMAP-Peer-Statement, signed with the same per\
    -runtime key; `kind` is \"control\", so a control notice never v\
    alidates as a peer statement and is never placed for an agent. C\
    LOSED at every level, and it carries no free text: the receivin\
    g runtime composes any agent-facing words itself (the delivery f\
    ailure notice of section \"Correlation and Replies\"). The schem\
    a cannot check that `about` names a peer message this runtime is\
    sued to the notice's signer; that is the receiving runtime's che\
    ck (section \"Control Notices\").",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "v",
    "key_id",
    "kind",
    "id",
    "from",
    "to",
    "ts",
    "about",
    "outcome",
    "cause"
  ],
  "properties": {
    "v": {
      "type": "integer",
      "const": 1
    },
    "key_id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,63}(?!\\n)$"
    },
    "kind": {
      "const": "control"
    },
    "id": {
      "type": "string",
      "description": "this notice's own id, minted like a peer messa\
    ge id; replay-checked in the same store, scoped to the signing r\
    untime.",
      "pattern": "^[A-Za-z0-9_][A-Za-z0-9_-]*(?!\\n)$"
    },
    "from": {
      "type": "string",
      "description": "the signing (receiving) runtime's configured r\
    untime address.",
      "pattern": "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9.-]+(?\
    !\\n)$"
    },
    "to": {
      "type": "string",
      "description": "the configured runtime address of the runtime \
    that signed the statement this notice is about.",
      "pattern": "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9.-]+(?\
    !\\n)$"
    },
    "ts": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9\
    ]{2}Z(?!\\n)$"
    },
    "about": {
      "type": "string",
      "description": "the `id` of the peer statement this notice is \
    about.",
      "pattern": "^[A-Za-z0-9_][A-Za-z0-9_-]*(?!\\n)$"
    },
    "outcome": {
      "enum": [
        "refused",
        "dropped",
        "demoted"
      ]
    },
    "cause": {
      "description": "why, from the outcome table of section \"Outco\
    mes\". `policy` is a deployment refusal (for example a first-sig\
    ht quarantine), named further by policy_code.",
      "enum": [
        "statement_value",
        "key_domain",
        "ts_window",
        "exposure_signer",
        "body_charset",
        "body_digest",
        "attachment_count",
        "attachment_digest",
        "message_id",
        "duplicate",
        "misrouted",
        "unresolved_reply",
        "no_edge",
        "policy"
      ]
    },
    "policy_code": {
      "type": "string",
      "description": "deployment-defined token, only with cause `pol\
    icy` (e.g. `quarantined`).",
      "pattern": "^[a-z][a-z0-9_]{0,63}(?!\\n)$"
    }
  },
  "allOf": [
    {
      "if": {
        "required": [
          "policy_code"
        ]
      },
      "then": {
        "properties": {
          "cause": {
            "const": "policy"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "cause": {
            "const": "policy"
          }
        },
        "required": [
          "cause"
        ]
      },
      "then": {
        "required": [
          "policy_code"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "outcome": {
            "const": "refused"
          }
        },
        "required": [
          "outcome"
        ]
      },
      "then": {
        "properties": {
          "cause": {
            "enum": [
              "unresolved_reply",
              "no_edge",
              "policy"
            ]
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "outcome": {
            "const": "dropped"
          }
        },
        "required": [
          "outcome"
        ]
      },
      "then": {
        "properties": {
          "cause": {
            "enum": [
              "duplicate",
              "misrouted"
            ]
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "outcome": {
            "const": "demoted"
          }
        },
        "required": [
          "outcome"
        ]
      },
      "then": {
        "properties": {
          "cause": {
            "enum": [
              "statement_value",
              "key_domain",
              "ts_window",
              "exposure_signer",
              "body_charset",
              "body_digest",
              "attachment_count",
              "attachment_digest",
              "message_id"
            ]
          }
        }
      }
    }
  ]
}

{
  "contract_version": "2",
  "notice_id": "n-index-mismatch",
  "ts": "2026-07-21T04:06:00Z",
  "kind": "deliver",
  "message": {
    "id": "46",
    "from": "colleague@example.com",
    "subject": "wrong content_ref",
    "preview": "descriptor points at another notice's sidecar",
    "mailbox": "inbox",
    "attachments": [
      { "filename": "photo.jpg", "media_type": "image/jpeg",
        "size_bytes": 204800,
        "disposition": "clean",
        "content_ref": "OTHER-NOTICE.attachments/7" }
    ]
  }
}

li.t:
mime/: 10 raw messages, and the candidate the selection rule of
 makes of each, reduced by a byte-exact
splitter;
